const tarefa = $json;
const versao = 'v26';
const administradora = String(tarefa.managerExternalId || '').replace(/\D/g, '');
const convidada = String(tarefa.targetExternalId || '').replace(/\D/g, '');

const recusar = (motivo) => [{ json: { taskId: tarefa.taskId, sucesso: false, outcome: String(motivo).slice(0, 500) } }];

if (!administradora || !convidada) return recusar('identificadores ausentes na tarefa');

async function chamar(url, corpo, loginCustomerId) {
  return this.helpers.httpRequestWithAuthentication.call(this, 'googleOAuth2Api', {
    method: 'POST',
    url,
    headers: { 'login-customer-id': loginCustomerId, 'Content-Type': 'application/json' },
    body: corpo,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
}

let resposta;

try {
  if (tarefa.kind === 'mcc_invite') {
    resposta = await chamar.call(
      this,
      `https://googleads.googleapis.com/${versao}/customers/${administradora}/customerClientLinks:mutate`,
      { operations: [{ create: { clientCustomer: `customers/${convidada}`, status: 'PENDING' } }] },
      administradora,
    );
  } else if (tarefa.kind === 'mcc_accept') {
    const pendentes = await this.helpers.httpRequestWithAuthentication.call(this, 'googleOAuth2Api', {
      method: 'POST',
      url: `https://googleads.googleapis.com/${versao}/customers/${convidada}/googleAds:search`,
      headers: { 'login-customer-id': convidada, 'Content-Type': 'application/json' },
      body: {
        query: `SELECT customer_manager_link.resource_name, customer_manager_link.manager_customer, customer_manager_link.status FROM customer_manager_link WHERE customer_manager_link.status = 'PENDING'`,
      },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });

    if (pendentes.statusCode < 200 || pendentes.statusCode >= 300) {
      return recusar(`não foi possível listar convites pendentes (HTTP ${pendentes.statusCode})`);
    }

    const vinculo = (pendentes.body?.results || []).find(
      (linha) => String(linha?.customerManagerLink?.managerCustomer || '').endsWith(`/${administradora}`),
    );

    if (!vinculo) return recusar('nenhum convite pendente desta administradora nesta conta');

    resposta = await chamar.call(
      this,
      `https://googleads.googleapis.com/${versao}/customers/${convidada}/customerManagerLinks:mutate`,
      {
        operations: [
          { update: { resourceName: vinculo.customerManagerLink.resourceName, status: 'ACTIVE' }, updateMask: 'status' },
        ],
      },
      convidada,
    );
  } else {
    return recusar(`tipo de tarefa desconhecido: ${tarefa.kind}`);
  }
} catch (erro) {
  return recusar(`falha de rede: ${erro.message}`);
}

if (resposta.statusCode >= 200 && resposta.statusCode < 300) {
  const recurso = resposta.body?.results?.[0]?.resourceName ?? 'concluído';
  const rotulo = tarefa.kind === 'mcc_invite' ? 'convite pendente' : 'vínculo ativo';
  return [{ json: { taskId: tarefa.taskId, sucesso: true, outcome: `${rotulo} · ${recurso}` } }];
}

const falha = resposta.body?.error?.details?.[0]?.errors?.[0];
const codigo = falha ? Object.values(falha.errorCode || {})[0] : null;
const mensagem = falha?.message || resposta.body?.error?.message || 'recusado sem mensagem';

return recusar(`${codigo ? codigo + ' · ' : ''}${mensagem} (HTTP ${resposta.statusCode})`);
